</main>
@if($mode === 'pending')<script>
const input=document.getElementById('videoInput'), preview=document.getElementById('preview'), player=document.getElementById('previewVideo'), loading=document.getElementById('loading'), send=document.getElementById('send'), replace=document.getElementById('replace'), error=document.getElementById('localError'), form=document.getElementById('evidenceForm'), uploadStatus=document.getElementById('uploadStatus'), uploadTitle=document.getElementById('uploadTitle'), uploadProgress=document.getElementById('uploadProgress'), uploadPercent=document.getElementById('uploadPercent'), uploadBytes=document.getElementById('uploadBytes'), processingNote=document.getElementById('processingNote'); let objectUrl=null, selectedVideoFile=null, uploading=false;
const formatSize=b=>b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(1)+' MB'; const formatDuration=s=>`00:${s.toFixed(2).padStart(5,'0')}`;
function clearPreview(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;selectedVideoFile=null;player.removeAttribute('src');preview.classList.add('hidden');send.disabled=true;error.classList.add('hidden');}
function showError(message){uploading=false;error.textContent=message;error.classList.remove('hidden');send.disabled=false;replace.disabled=false;input.disabled=false;document.getElementById('picker').classList.remove('hidden');uploadStatus.classList.add('hidden');processingNote.classList.add('hidden');}
input.addEventListener('change',()=>{const file=input.files[0];clearPreview();if(!file)return;selectedVideoFile=file;loading.classList.remove('hidden');objectUrl=URL.createObjectURL(selectedVideoFile);player.src=objectUrl;player.onloadedmetadata=()=>{loading.classList.add('hidden');preview.classList.remove('hidden');document.getElementById('duration').textContent=formatDuration(player.duration);document.getElementById('size').textContent=formatSize(selectedVideoFile.size);if(!Number.isFinite(player.duration)||player.duration>10){error.textContent=`Este vídeo possui ${player.duration.toFixed(2)} segundos. O limite é de 10 segundos.`;error.classList.remove('hidden');send.disabled=true;return;}send.disabled=false;};player.onerror=()=>{loading.classList.add('hidden');preview.classList.remove('hidden');error.textContent='Não foi possível ler os metadados deste vídeo. Escolha outro arquivo.';error.classList.remove('hidden');};});
replace.addEventListener('click',()=>{if(!uploading){clearPreview();input.value='';input.click();}});form.addEventListener('submit',event=>{event.preventDefault();if(uploading)return;if(!(selectedVideoFile instanceof File)){showError('Selecione um vídeo antes de enviar.');return;}uploading=true;send.disabled=true;replace.disabled=true;input.disabled=true;document.getElementById('picker').classList.add('hidden');uploadStatus.classList.remove('hidden');uploadTitle.textContent='Enviando vídeo...';uploadProgress.style.width='0%';uploadPercent.textContent='0%';uploadBytes.textContent=`0 MB de ${formatSize(selectedVideoFile.size)}`;processingNote.classList.add('hidden');const data=new FormData();data.append('_token',form.querySelector('[name=_token]').value);data.append('video',selectedVideoFile,selectedVideoFile.name);const xhr=new XMLHttpRequest();xhr.open('POST',form.action);xhr.responseType='text';xhr.timeout=600000;xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-CSRF-TOKEN',form.querySelector('[name=_token]').value);xhr.upload.onprogress=event=>{if(!event.lengthComputable)return;const percent=Math.min(100,Math.round(event.loaded/event.total*100));uploadProgress.style.width=`${percent}%`;uploadPercent.textContent=`${percent}%`;uploadBytes.textContent=`${formatSize(event.loaded)} de ${formatSize(event.total)}`;};xhr.upload.onload=()=>{uploadProgress.style.width='100%';uploadPercent.textContent='100%';uploadBytes.textContent=`${formatSize(selectedVideoFile.size)} de ${formatSize(selectedVideoFile.size)}`;uploadTitle.textContent='Vídeo enviado. Processando...';processingNote.classList.remove('hidden');};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){window.location.assign(xhr.responseURL||window.location.href);return;}let message='Não foi possível concluir o processamento. Tente novamente.';try{const body=JSON.parse(xhr.responseText);message=Object.values(body.errors||{}).flat().join(' ')||body.message||message;}catch(e){}showError(message);};xhr.onerror=xhr.ontimeout=()=>showError('Não foi possível concluir o processamento. Tente novamente.');xhr.send(data);});window.addEventListener('pagehide',clearPreview);
</script>@endif
</html>
